"""Exceptions raised by the minisql package."""


class QueryError(Exception):
    """Raised for any problem with a query."""

"""Abstract syntax tree nodes for minisql queries."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any, List, Optional, Tuple, Union


@dataclass(frozen=True)
class Literal:
    value: Any
    # One of "int", "float", "str", "bool", "null".  Kept separately from the
    # value because Python considers True == 1 and 1 == 1.0.
    kind: str


@dataclass(frozen=True)
class Column:
    name: str
    index: int = -1


@dataclass(frozen=True)
class Unary:
    op: str
    operand: Expr


@dataclass(frozen=True)
class Binary:
    op: str
    left: Expr
    right: Expr


@dataclass(frozen=True)
class Not:
    operand: Expr


@dataclass(frozen=True)
class IsNull:
    operand: Expr
    negate: bool


@dataclass(frozen=True)
class InList:
    operand: Expr
    items: Tuple[Expr, ...]
    negate: bool


@dataclass(frozen=True)
class Between:
    operand: Expr
    low: Expr
    high: Expr
    negate: bool


@dataclass(frozen=True)
class Like:
    operand: Expr
    pattern: Expr
    negate: bool


@dataclass(frozen=True)
class Func:
    name: str
    args: Tuple[Expr, ...]
    star: bool = False
    aggregate: bool = False


Expr = Union[
    Literal,
    Column,
    Unary,
    Binary,
    Not,
    IsNull,
    InList,
    Between,
    Like,
    Func,
]


@dataclass
class SelectItem:
    expr: Expr
    alias: Optional[str]
    text: str


@dataclass
class OrderItem:
    expr: Expr
    desc: bool
    text: str
    bare_name: Optional[str] = None
    bare_int: Optional[int] = None


@dataclass
class Query:
    distinct: bool
    star: bool
    items: List[SelectItem]
    table: str
    where: Optional[Expr]
    group_by: List[Expr]
    having: Optional[Expr]
    order_by: List[OrderItem]
    limit: Optional[int]
    offset: Optional[int]

"""Recursive-descent parser for minisql SELECT statements."""

from __future__ import annotations

from typing import List, Optional, Tuple

from ._ast import (
    Between,
    Binary,
    Column,
    Expr,
    Func,
    InList,
    IsNull,
    Like,
    Literal,
    Not,
    OrderItem,
    Query,
    SelectItem,
    Unary,
)
from ._errors import QueryError
from ._lexer import Token, tokenize

_AGGREGATES = frozenset({"COUNT", "SUM", "AVG", "MIN", "MAX"})

# name -> (minimum arguments, maximum arguments or None for no maximum)
_SCALAR_FUNCTIONS = {
    "LOWER": (1, 1),
    "UPPER": (1, 1),
    "LENGTH": (1, 1),
    "ABS": (1, 1),
    "ROUND": (1, 2),
    "COALESCE": (1, None),
}

_COMPARISON_OPERATORS = frozenset({"=", "!=", "<>", "<", "<=", ">", ">="})


class Parser:
    def __init__(self, sql: str) -> None:
        self.sql = sql
        self.tokens = tokenize(sql)
        self.pos = 0

    # ------------------------------------------------------------------
    # Token helpers
    # ------------------------------------------------------------------
    def _peek(self, offset: int = 0) -> Token:
        index = self.pos + offset
        if index >= len(self.tokens):
            return self.tokens[-1]
        return self.tokens[index]

    def _advance(self) -> Token:
        token = self._peek()
        self.pos += 1
        return token

    def _previous(self) -> Token:
        return self.tokens[self.pos - 1]

    def _at_keyword(self, keyword: str) -> bool:
        token = self._peek()
        return token.kind == "KEYWORD" and token.value == keyword

    def _match_keyword(self, keyword: str) -> bool:
        if self._at_keyword(keyword):
            self.pos += 1
            return True
        return False

    def _expect_keyword(self, keyword: str) -> Token:
        if not self._at_keyword(keyword):
            raise QueryError("syntax error: expected {}".format(keyword))
        return self._advance()

    def _at_op(self, operator: str) -> bool:
        token = self._peek()
        return token.kind == "OP" and token.value == operator

    def _match_op(self, operator: str) -> bool:
        if self._at_op(operator):
            self.pos += 1
            return True
        return False

    def _expect_op(self, operator: str) -> Token:
        if not self._at_op(operator):
            raise QueryError("syntax error: expected {!r}".format(operator))
        return self._advance()

    def _expect_name(self) -> str:
        token = self._peek()
        if token.kind != "IDENT":
            raise QueryError("syntax error: expected a name")
        self.pos += 1
        return str(token.value)

    # ------------------------------------------------------------------
    # Statement
    # ------------------------------------------------------------------
    def parse(self) -> Query:
        self._expect_keyword("SELECT")
        distinct = self._match_keyword("DISTINCT")

        star = False
        items: List[SelectItem] = []
        if self._at_op("*"):
            self._advance()
            star = True
        else:
            items.append(self._parse_select_item())
            while self._match_op(","):
                items.append(self._parse_select_item())

        self._expect_keyword("FROM")
        table = self._expect_name()

        where: Optional[Expr] = None
        if self._match_keyword("WHERE"):
            where = self._parse_expression()

        group_by: List[Expr] = []
        if self._match_keyword("GROUP"):
            self._expect_keyword("BY")
            group_by.append(self._parse_expression())
            while self._match_op(","):
                group_by.append(self._parse_expression())

        having: Optional[Expr] = None
        if self._match_keyword("HAVING"):
            having = self._parse_expression()

        order_by: List[OrderItem] = []
        if self._match_keyword("ORDER"):
            self._expect_keyword("BY")
            order_by.append(self._parse_order_item())
            while self._match_op(","):
                order_by.append(self._parse_order_item())

        limit: Optional[int] = None
        offset: Optional[int] = None
        if self._match_keyword("LIMIT"):
            limit = self._parse_limit_value("LIMIT")
            if self._match_keyword("OFFSET"):
                offset = self._parse_limit_value("OFFSET")

        self._match_op(";")
        if self._peek().kind != "EOF":
            raise QueryError("syntax error: unexpected token {!r}".format(self._peek().value))

        return Query(
            distinct=distinct,
            star=star,
            items=items,
            table=table,
            where=where,
            group_by=group_by,
            having=having,
            order_by=order_by,
            limit=limit,
            offset=offset,
        )

    def _parse_limit_value(self, clause: str) -> int:
        token = self._peek()
        if token.kind != "NUMBER" or not isinstance(token.value, int) or isinstance(token.value, bool):
            raise QueryError("syntax error: {} requires a non-negative integer".format(clause))
        self._advance()
        if token.value < 0:
            raise QueryError("syntax error: {} requires a non-negative integer".format(clause))
        return token.value

    def _parse_select_item(self) -> SelectItem:
        start_pos = self.pos
        first = self._peek()
        expr = self._parse_expression()
        end = self._previous().end
        text = self.sql[first.start:end]

        alias: Optional[str] = None
        if self._match_keyword("AS"):
            alias = self._expect_name()
        elif self._peek().kind == "IDENT":
            alias = str(self._advance().value)

        return SelectItem(expr=expr, alias=alias, text=text)

    def _parse_order_item(self) -> OrderItem:
        start_pos = self.pos
        first = self._peek()
        expr = self._parse_expression()
        end = self._previous().end
        text = self.sql[first.start:end]

        desc = False
        if self._match_keyword("ASC"):
            pass
        elif self._match_keyword("DESC"):
            desc = True

        bare_name: Optional[str] = None
        bare_int: Optional[int] = None
        if self.pos - 1 == start_pos:
            if first.kind == "IDENT" and isinstance(expr, Column):
                bare_name = expr.name
            elif (
                first.kind == "NUMBER"
                and isinstance(expr, Literal)
                and expr.kind == "int"
            ):
                bare_int = int(expr.value)

        return OrderItem(
            expr=expr,
            desc=desc,
            text=text,
            bare_name=bare_name,
            bare_int=bare_int,
        )

    # ------------------------------------------------------------------
    # Expressions, lowest precedence first
    # ------------------------------------------------------------------
    def _parse_expression(self) -> Expr:
        return self._parse_or()

    def _parse_or(self) -> Expr:
        left = self._parse_and()
        while self._match_keyword("OR"):
            right = self._parse_and()
            left = Binary("or", left, right)
        return left

    def _parse_and(self) -> Expr:
        left = self._parse_not()
        while self._match_keyword("AND"):
            right = self._parse_not()
            left = Binary("and", left, right)
        return left

    def _parse_not(self) -> Expr:
        if self._match_keyword("NOT"):
            return Not(self._parse_not())
        return self._parse_comparison()

    def _parse_comparison(self) -> Expr:
        left = self._parse_additive()
        token = self._peek()

        if token.kind == "OP" and token.value in _COMPARISON_OPERATORS:
            operator = str(token.value)
            self._advance()
            right = self._parse_additive()
            return Binary(operator, left, right)

        if self._match_keyword("IS"):
            negate = self._match_keyword("NOT")
            if not self._match_keyword("NULL"):
                raise QueryError("syntax error: expected NULL after IS")
            return IsNull(left, negate)

        if self._match_keyword("NOT"):
            if self._match_keyword("IN"):
                return InList(left, self._parse_in_list(), True)
            if self._match_keyword("BETWEEN"):
                low = self._parse_additive()
                self._expect_keyword("AND")
                high = self._parse_additive()
                return Between(left, low, high, True)
            if self._match_keyword("LIKE"):
                pattern = self._parse_additive()
                return Like(left, pattern, True)
            raise QueryError("syntax error: expected IN, BETWEEN, or LIKE after NOT")

        if self._match_keyword("IN"):
            return InList(left, self._parse_in_list(), False)

        if self._match_keyword("BETWEEN"):
            low = self._parse_additive()
            self._expect_keyword("AND")
            high = self._parse_additive()
            return Between(left, low, high, False)

        if self._match_keyword("LIKE"):
            pattern = self._parse_additive()
            return Like(left, pattern, False)

        return left

    def _parse_in_list(self) -> Tuple[Expr, ...]:
        self._expect_op("(")
        items = [self._parse_expression()]
        while self._match_op(","):
            items.append(self._parse_expression())
        self._expect_op(")")
        return tuple(items)

    def _parse_additive(self) -> Expr:
        left = self._parse_multiplicative()
        while True:
            token = self._peek()
            if token.kind == "OP" and token.value in ("+", "-", "||"):
                operator = str(token.value)
                self._advance()
                right = self._parse_multiplicative()
                left = Binary(operator, left, right)
            else:
                return left

    def _parse_multiplicative(self) -> Expr:
        left = self._parse_unary()
        while True:
            token = self._peek()
            if token.kind == "OP" and token.value in ("*", "/"):
                operator = str(token.value)
                self._advance()
                right = self._parse_unary()
                left = Binary(operator, left, right)
            else:
                return left

    def _parse_unary(self) -> Expr:
        if self._at_op("-"):
            self._advance()
            return Unary("-", self._parse_unary())
        return self._parse_atom()

    def _parse_atom(self) -> Expr:
        token = self._peek()

        if token.kind == "NUMBER":
            self._advance()
            if isinstance(token.value, int) and not isinstance(token.value, bool):
                return Literal(token.value, "int")
            return Literal(token.value, "float")

        if token.kind == "STRING":
            self._advance()
            return Literal(token.value, "str")

        if token.kind == "KEYWORD":
            if token.value == "NULL":
                self._advance()
                return Literal(None, "null")
            if token.value == "TRUE":
                self._advance()
                return Literal(True, "bool")
            if token.value == "FALSE":
                self._advance()
                return Literal(False, "bool")
            raise QueryError("syntax error: unexpected keyword {}".format(token.value))

        if token.kind == "IDENT":
            self._advance()
            if self._at_op("("):
                return self._parse_function(str(token.value))
            return Column(str(token.value))

        if token.kind == "OP" and token.value == "(":
            self._advance()
            expr = self._parse_expression()
            self._expect_op(")")
            return expr

        raise QueryError("syntax error: expected an expression")

    def _parse_function(self, raw_name: str) -> Expr:
        name = raw_name.upper()
        self._expect_op("(")

        if name == "COUNT" and self._at_op("*"):
            self._advance()
            self._expect_op(")")
            return Func("COUNT", (), star=True, aggregate=True)

        args: List[Expr] = []
        if not self._at_op(")"):
            args.append(self._parse_expression())
            while self._match_op(","):
                args.append(self._parse_expression())
        self._expect_op(")")

        if name in _AGGREGATES:
            if len(args) != 1:
                raise QueryError(
                    "function {} expects 1 argument, got {}".format(name, len(args))
                )
            return Func(name, tuple(args), aggregate=True)

        arity = _SCALAR_FUNCTIONS.get(name)
        if arity is None:
            raise QueryError("unknown function: {}".format(raw_name))
        minimum, maximum = arity
        if len(args) < minimum or (maximum is not None and len(args) > maximum):
            if maximum is None:
                expected = "at least {}".format(minimum)
            elif minimum == maximum:
                expected = str(minimum)
            else:
                expected = "{} to {}".format(minimum, maximum)
            raise QueryError(
                "function {} expects {} argument(s), got {}".format(
                    name, expected, len(args)
                )
            )
        return Func(name, tuple(args), aggregate=False)


def parse(sql: str) -> Query:
    return Parser(sql).parse()

"""Execution engine for minisql."""

from __future__ import annotations

import csv
import os
import re
from dataclasses import dataclass
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from functools import cmp_to_key, lru_cache
from typing import Any, Dict, Iterable, List, Optional, Sequence, Tuple

from ._ast import (
    Between,
    Binary,
    Column,
    Expr,
    Func,
    InList,
    IsNull,
    Like,
    Literal,
    Not,
    Query,
    SelectItem,
    Unary,
)
from ._errors import QueryError

_INT_RE = re.compile(r"-?[0-9]+\Z")
_DECIMAL_RE = re.compile(r"-?(?:[0-9]+\.[0-9]*|[0-9]*\.[0-9]+)\Z")


@dataclass
class Table:
    header: List[str]
    rows: List[Tuple[Any, ...]]


@dataclass
class _OrderKey:
    expr: Optional[Expr]
    index: Optional[int]
    desc: bool


@dataclass
class Result:
    columns: List[str]
    rows: List[Tuple[Any, ...]]


# ----------------------------------------------------------------------
# Loading CSV tables
# ----------------------------------------------------------------------
def _convert_field(field: str) -> Any:
    if field == "":
        return None
    if _INT_RE.fullmatch(field):
        return int(field)
    if _DECIMAL_RE.fullmatch(field):
        return float(field)
    return field


def load_table(directory: Any, name: str) -> Table:
    try:
        directory = os.fspath(directory)
    except TypeError:
        raise QueryError("invalid directory")

    path = os.path.join(directory, name + ".csv")
    try:
        with open(path, "r", newline="", encoding="utf-8") as handle:
            reader = csv.reader(handle)
            try:
                header = next(reader)
            except StopIteration:
                raise QueryError("table {!r} is empty".format(name))

            rows: List[Tuple[Any, ...]] = []
            for line_number, raw in enumerate(reader, start=2):
                if len(raw) != len(header):
                    raise QueryError(
                        "table {!r}: row {} has {} field(s), expected {}".format(
                            name, line_number, len(raw), len(header)
                        )
                    )
                rows.append(tuple(_convert_field(field) for field in raw))
    except FileNotFoundError:
        raise QueryError("table {!r} not found".format(name))
    except (OSError, UnicodeError, csv.Error) as exc:
        raise QueryError("cannot read table {!r}: {}".format(name, exc))

    return Table(header, rows)


# ----------------------------------------------------------------------
# Expression helpers
# ----------------------------------------------------------------------
def _is_number(value: Any) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _type_name(value: Any) -> str:
    if isinstance(value, bool):
        return "a boolean"
    if _is_number(value):
        return "a number"
    if isinstance(value, str):
        return "a string"
    return "a value"


def _children(expr: Expr) -> Tuple[Expr, ...]:
    if isinstance(expr, Unary):
        return (expr.operand,)
    if isinstance(expr, Binary):
        return (expr.left, expr.right)
    if isinstance(expr, Not):
        return (expr.operand,)
    if isinstance(expr, IsNull):
        return (expr.operand,)
    if isinstance(expr, InList):
        return (expr.operand,) + expr.items
    if isinstance(expr, Between):
        return (expr.operand, expr.low, expr.high)
    if isinstance(expr, Like):
        return (expr.operand, expr.pattern)
    if isinstance(expr, Func):
        return expr.args
    return ()


def _expr_equal(left: Expr, right: Expr) -> bool:
    if type(left) is not type(right):
        return False
    if isinstance(left, Literal):
        return left.kind == right.kind and left.value == right.value
    if isinstance(left, Column):
        return left.index == right.index
    if isinstance(left, Unary):
        return left.op == right.op and _expr_equal(left.operand, right.operand)
    if isinstance(left, Binary):
        return (
            left.op == right.op
            and _expr_equal(left.left, right.left)
            and _expr_equal(left.right, right.right)
        )
    if isinstance(left, Not):
        return _expr_equal(left.operand, right.operand)
    if isinstance(left, IsNull):
        return left.negate == right.negate and _expr_equal(
            left.operand, right.operand
        )
    if isinstance(left, InList):
        return (
            left.negate == right.negate
            and _expr_equal(left.operand, right.operand)
            and len(left.items) == len(right.items)
            and all(_expr_equal(a, b) for a, b in zip(left.items, right.items))
        )
    if isinstance(left, Between):
        return (
            left.negate == right.negate
            and _expr_equal(left.operand, right.operand)
            and _expr_equal(left.low, right.low)
            and _expr_equal(left.high, right.high)
        )
    if isinstance(left, Like):
        return (
            left.negate == right.negate
            and _expr_equal(left.operand, right.operand)
            and _expr_equal(left.pattern, right.pattern)
        )
    if isinstance(left, Func):
        return (
            left.name == right.name
            and left.star == right.star
            and left.aggregate == right.aggregate
            and len(left.args) == len(right.args)
            and all(_expr_equal(a, b) for a, b in zip(left.args, right.args))
        )
    return left == right


def _has_aggregate(expr: Expr) -> bool:
    if isinstance(expr, Func) and expr.aggregate:
        return True
    return any(_has_aggregate(child) for child in _children(expr))


def _check_aggregates(expr: Expr, inside_aggregate: bool = False) -> None:
    if isinstance(expr, Func) and expr.aggregate:
        if inside_aggregate:
            raise QueryError("aggregate functions cannot be nested")
        for arg in expr.args:
            _check_aggregates(arg, True)
        return
    for child in _children(expr):
        _check_aggregates(child, inside_aggregate)


def _bind_expr(
    expr: Expr, lookup: Dict[str, Tuple[int, str]]
) -> Expr:
    if isinstance(expr, Literal):
        return expr
    if isinstance(expr, Column):
        if expr.index >= 0:
            return expr
        entry = lookup.get(expr.name.casefold())
        if entry is None:
            raise QueryError("unknown column: {}".format(expr.name))
        index, header_name = entry
        return Column(header_name, index)
    if isinstance(expr, Unary):
        return Unary(expr.op, _bind_expr(expr.operand, lookup))
    if isinstance(expr, Binary):
        return Binary(
            expr.op,
            _bind_expr(expr.left, lookup),
            _bind_expr(expr.right, lookup),
        )
    if isinstance(expr, Not):
        return Not(_bind_expr(expr.operand, lookup))
    if isinstance(expr, IsNull):
        return IsNull(_bind_expr(expr.operand, lookup), expr.negate)
    if isinstance(expr, InList):
        return InList(
            _bind_expr(expr.operand, lookup),
            tuple(_bind_expr(item, lookup) for item in expr.items),
            expr.negate,
        )
    if isinstance(expr, Between):
        return Between(
            _bind_expr(expr.operand, lookup),
            _bind_expr(expr.low, lookup),
            _bind_expr(expr.high, lookup),
            expr.negate,
        )
    if isinstance(expr, Like):
        return Like(
            _bind_expr(expr.operand, lookup),
            _bind_expr(expr.pattern, lookup),
            expr.negate,
        )
    if isinstance(expr, Func):
        return Func(
            expr.name,
            tuple(_bind_expr(arg, lookup) for arg in expr.args),
            expr.star,
            expr.aggregate,
        )
    raise QueryError("invalid expression")


def _validate_grouped(expr: Expr, group_exprs: Sequence[Expr]) -> None:
    if any(_expr_equal(expr, group_expr) for group_expr in group_exprs):
        return
    if isinstance(expr, Literal):
        return
    if isinstance(expr, Func) and expr.aggregate:
        return
    if isinstance(expr, Column):
        raise QueryError(
            "column {} must appear in GROUP BY or be used in an aggregate".format(
                expr.name
            )
        )
    for child in _children(expr):
        _validate_grouped(child, group_exprs)


# ----------------------------------------------------------------------
# Scalar semantics
# ----------------------------------------------------------------------
def _to_bool(value: Any) -> Optional[bool]:
    if value is None:
        return None
    if isinstance(value, bool):
        return value
    raise QueryError("condition must be a boolean")


def _truth(value: Any) -> bool:
    return _to_bool(value) is True


def _not3(value: Optional[bool]) -> Optional[bool]:
    if value is None:
        return None
    return not value


def _and3(left: Optional[bool], right: Optional[bool]) -> Optional[bool]:
    if left is False or right is False:
        return False
    if left is None or right is None:
        return None
    return True


def _or3(left: Optional[bool], right: Optional[bool]) -> Optional[bool]:
    if left is True or right is True:
        return True
    if left is None or right is None:
        return None
    return False


def _compare_values(left: Any, right: Any) -> int:
    if _is_number(left) and _is_number(right):
        if left < right:
            return -1
        if left > right:
            return 1
        return 0
    if isinstance(left, bool) and isinstance(right, bool):
        if left < right:
            return -1
        if left > right:
            return 1
        return 0
    if isinstance(left, str) and isinstance(right, str):
        if left < right:
            return -1
        if left > right:
            return 1
        return 0
    raise QueryError(
        "cannot compare {} with {}".format(_type_name(left), _type_name(right))
    )


def _sql_compare(operator: str, left: Any, right: Any) -> Optional[bool]:
    if left is None or right is None:
        return None
    comparison = _compare_values(left, right)
    if operator == "=":
        return comparison == 0
    if operator in ("!=", "<>"):
        return comparison != 0
    if operator == "<":
        return comparison < 0
    if operator == "<=":
        return comparison <= 0
    if operator == ">":
        return comparison > 0
    if operator == ">=":
        return comparison >= 0
    raise QueryError("unknown comparison operator: {}".format(operator))


@lru_cache(maxsize=128)
def _like_pattern(pattern: str) -> "re.Pattern[str]":
    parts = []
    for character in pattern:
        if character == "%":
            parts.append(".*")
        elif character == "_":
            parts.append(".")
        else:
            parts.append(re.escape(character))
    return re.compile("".join(parts), re.DOTALL)


def _like(value: str, pattern: str) -> bool:
    return _like_pattern(pattern).fullmatch(value) is not None


def _text(value: Any) -> str:
    if isinstance(value, str):
        return value
    return str(value)


def _round_to_int(value: Any) -> int:
    try:
        return int(
            Decimal(str(value)).quantize(Decimal(1), rounding=ROUND_HALF_UP)
        )
    except (InvalidOperation, ValueError, OverflowError):
        raise QueryError("cannot round value")


def _round_to_places(value: Any, places: int) -> float:
    try:
        quantum = Decimal(1).scaleb(-places)
        rounded = Decimal(str(value)).quantize(quantum, rounding=ROUND_HALF_UP)
        return float(rounded)
    except (InvalidOperation, ValueError, OverflowError):
        raise QueryError("cannot round value")


# ----------------------------------------------------------------------
# Expression evaluation
# ----------------------------------------------------------------------
def evaluate(expr: Expr, row: Optional[Tuple[Any, ...]], group: Optional[List[Tuple[Any, ...]]]) -> Any:
    if isinstance(expr, Literal):
        return expr.value

    if isinstance(expr, Column):
        if row is None:
            raise QueryError("column {} is not available".format(expr.name))
        return row[expr.index]

    if isinstance(expr, Unary):
        value = evaluate(expr.operand, row, group)
        if value is None:
            return None
        if not _is_number(value):
            raise QueryError("unary - requires a number")
        return -value

    if isinstance(expr, Not):
        return _not3(_to_bool(evaluate(expr.operand, row, group)))

    if isinstance(expr, Binary):
        return _evaluate_binary(expr, row, group)

    if isinstance(expr, IsNull):
        value = evaluate(expr.operand, row, group)
        return (value is None) != expr.negate

    if isinstance(expr, InList):
        return _evaluate_in_list(expr, row, group)

    if isinstance(expr, Between):
        value = evaluate(expr.operand, row, group)
        low = evaluate(expr.low, row, group)
        high = evaluate(expr.high, row, group)
        result = _and3(
            _sql_compare("<=", low, value),
            _sql_compare("<=", value, high),
        )
        return _not3(result) if expr.negate else result

    if isinstance(expr, Like):
        value = evaluate(expr.operand, row, group)
        pattern = evaluate(expr.pattern, row, group)
        if value is None or pattern is None:
            return None
        if not isinstance(value, str) or not isinstance(pattern, str):
            raise QueryError("LIKE requires string operands")
        matched = _like(value, pattern)
        return not matched if expr.negate else matched

    if isinstance(expr, Func):
        if expr.aggregate:
            return _evaluate_aggregate(expr, group)
        return _evaluate_scalar(expr, row, group)

    raise QueryError("invalid expression")


def _evaluate_binary(
    expr: Binary, row: Optional[Tuple[Any, ...]], group: Optional[List[Tuple[Any, ...]]]
) -> Any:
    operator = expr.op

    if operator == "and":
        left = _to_bool(evaluate(expr.left, row, group))
        if left is False:
            return False
        right = _to_bool(evaluate(expr.right, row, group))
        return _and3(left, right)

    if operator == "or":
        left = _to_bool(evaluate(expr.left, row, group))
        if left is True:
            return True
        right = _to_bool(evaluate(expr.right, row, group))
        return _or3(left, right)

    left = evaluate(expr.left, row, group)
    right = evaluate(expr.right, row, group)

    if operator in ("+", "-", "*", "/"):
        if left is None or right is None:
            return None
        if not _is_number(left) or not _is_number(right):
            raise QueryError("arithmetic requires numeric operands")
        if operator == "/":
            if right == 0:
                return None
            return left / right
        if isinstance(left, int) and isinstance(right, int):
            if operator == "+":
                return left + right
            if operator == "-":
                return left - right
            return left * right
        left_float = float(left)
        right_float = float(right)
        if operator == "+":
            return left_float + right_float
        if operator == "-":
            return left_float - right_float
        return left_float * right_float

    if operator == "||":
        if left is None or right is None:
            return None
        return _text(left) + _text(right)

    return _sql_compare(operator, left, right)


def _evaluate_in_list(
    expr: InList, row: Optional[Tuple[Any, ...]], group: Optional[List[Tuple[Any, ...]]]
) -> Optional[bool]:
    value = evaluate(expr.operand, row, group)
    if value is None:
        return None

    saw_null = False
    for item_expr in expr.items:
        item = evaluate(item_expr, row, group)
        if item is None:
            saw_null = True
            continue
        if _sql_compare("=", value, item) is True:
            result: Optional[bool] = True
            return _not3(result) if expr.negate else result

    result = None if saw_null else False
    return _not3(result) if expr.negate else result


def _evaluate_scalar(
    expr: Func, row: Optional[Tuple[Any, ...]], group: Optional[List[Tuple[Any, ...]]]
) -> Any:
    name = expr.name

    if name == "COALESCE":
        for argument in expr.args:
            value = evaluate(argument, row, group)
            if value is not None:
                return value
        return None

    values = [evaluate(argument, row, group) for argument in expr.args]
    if any(value is None for value in values):
        return None

    if name == "LOWER":
        value = values[0]
        if not isinstance(value, str):
            raise QueryError("LOWER requires a string")
        return value.lower()

    if name == "UPPER":
        value = values[0]
        if not isinstance(value, str):
            raise QueryError("UPPER requires a string")
        return value.upper()

    if name == "LENGTH":
        value = values[0]
        if not isinstance(value, str):
            raise QueryError("LENGTH requires a string")
        return len(value)

    if name == "ABS":
        value = values[0]
        if not _is_number(value):
            raise QueryError("ABS requires a number")
        return abs(value)

    if name == "ROUND":
        value = values[0]
        if not _is_number(value):
            raise QueryError("ROUND requires a number")
        if len(values) == 1:
            return _round_to_int(value)
        places = values[1]
        if not isinstance(places, int) or isinstance(places, bool):
            raise QueryError("ROUND requires an integer number of decimal places")
        return _round_to_places(value, places)

    raise QueryError("unknown function: {}".format(name))


def _evaluate_aggregate(
    expr: Func, group: Optional[List[Tuple[Any, ...]]]
) -> Any:
    if group is None:
        raise QueryError("aggregate function used outside a grouped query")

    name = expr.name
    if expr.star:
        return len(group)

    argument = expr.args[0]

    if name == "COUNT":
        count = 0
        for row in group:
            if evaluate(argument, row, None) is not None:
                count += 1
        return count

    values: List[Any] = []
    for row in group:
        value = evaluate(argument, row, None)
        if value is not None:
            values.append(value)

    if not values:
        return None

    if name == "SUM":
        for value in values:
            if not _is_number(value):
                raise QueryError("SUM requires numeric values")
        total: Any = 0
        for value in values:
            total += value
        return total

    if name == "AVG":
        for value in values:
            if not _is_number(value):
                raise QueryError("AVG requires numeric values")
        total = 0
        for value in values:
            total += value
        return total / len(values)

    if name == "MIN":
        best = values[0]
        for value in values[1:]:
            if _compare_values(value, best) < 0:
                best = value
        return best

    if name == "MAX":
        best = values[0]
        for value in values[1:]:
            if _compare_values(value, best) > 0:
                best = value
        return best

    raise QueryError("unknown aggregate function: {}".format(name))


# ----------------------------------------------------------------------
# Query execution
# ----------------------------------------------------------------------
def _value_key(value: Any) -> Tuple[Any, ...]:
    if value is None:
        return (0,)
    if isinstance(value, bool):
        return (1, value)
    if _is_number(value):
        return (2, value)
    if isinstance(value, str):
        return (3, value)
    return (4, repr(value))


def _compare_for_sort(left: Any, right: Any, descending: bool) -> int:
    if left is None and right is None:
        return 0
    if left is None:
        return 1 if descending else -1
    if right is None:
        return -1 if descending else 1
    comparison = _compare_values(left, right)
    return -comparison if descending else comparison


def execute(query: Query, table: Table) -> Result:
    lookup: Dict[str, Tuple[int, str]] = {}
    for index, header_name in enumerate(table.header):
        lookup.setdefault(header_name.casefold(), (index, header_name))

    if query.star:
        raw_items = [
            SelectItem(Column(header_name, index), None, header_name)
            for index, header_name in enumerate(table.header)
        ]
    else:
        raw_items = query.items

    items = [
        SelectItem(_bind_expr(item.expr, lookup), item.alias, item.text)
        for item in raw_items
    ]

    columns: List[str] = []
    for item in items:
        if item.alias is not None:
            columns.append(item.alias)
        elif isinstance(item.expr, Column):
            columns.append(item.expr.name)
        else:
            columns.append(item.text)

    output_lookup: Dict[str, int] = {}
    for index, column_name in enumerate(columns):
        output_lookup.setdefault(column_name.casefold(), index)

    order_keys: List[_OrderKey] = []
    for order_item in query.order_by:
        if (
            order_item.bare_name is not None
            and order_item.bare_name.casefold() in output_lookup
        ):
            order_keys.append(
                _OrderKey(
                    None,
                    output_lookup[order_item.bare_name.casefold()],
                    order_item.desc,
                )
            )
            continue

        if order_item.bare_int is not None:
            index = order_item.bare_int - 1
            if index < 0 or index >= len(items):
                raise QueryError(
                    "ORDER BY position {} is out of range".format(
                        order_item.bare_int
                    )
                )
            order_keys.append(_OrderKey(None, index, order_item.desc))
            continue

        order_keys.append(
            _OrderKey(
                _bind_expr(order_item.expr, lookup),
                None,
                order_item.desc,
            )
        )

    where = _bind_expr(query.where, lookup) if query.where is not None else None
    group_by = [_bind_expr(expr, lookup) for expr in query.group_by]
    having = _bind_expr(query.having, lookup) if query.having is not None else None

    expressions: List[Expr] = [item.expr for item in items]
    expressions.extend(group_by)
    if where is not None:
        expressions.append(where)
    if having is not None:
        expressions.append(having)
    for order_key in order_keys:
        if order_key.expr is not None:
            expressions.append(order_key.expr)

    for expression in expressions:
        _check_aggregates(expression)

    if where is not None and _has_aggregate(where):
        raise QueryError("aggregate functions cannot be used in WHERE")
    for expression in group_by:
        if _has_aggregate(expression):
            raise QueryError("aggregate functions cannot be used in GROUP BY")

    grouped = (
        bool(group_by)
        or any(_has_aggregate(item.expr) for item in items)
        or (having is not None and _has_aggregate(having))
        or any(
            order_key.expr is not None and _has_aggregate(order_key.expr)
            for order_key in order_keys
        )
    )

    if grouped:
        for item in items:
            _validate_grouped(item.expr, group_by)
        if having is not None:
            _validate_grouped(having, group_by)
        for order_key in order_keys:
            if order_key.expr is not None:
                _validate_grouped(order_key.expr, group_by)

    entries: List[Tuple[Tuple[Any, ...], List[Any]]] = []

    if not grouped:
        for row in table.rows:
            if where is not None and not _truth(evaluate(where, row, None)):
                continue
            if having is not None and not _truth(evaluate(having, row, None)):
                continue
            values = tuple(evaluate(item.expr, row, None) for item in items)
            keys = _make_order_keys(order_keys, values, row, None)
            entries.append((values, keys))
    else:
        filtered: List[Tuple[Any, ...]] = []
        for row in table.rows:
            if where is not None and not _truth(evaluate(where, row, None)):
                continue
            filtered.append(row)

        if group_by:
            groups: List[List[Tuple[Any, ...]]] = []
            group_lookup: Dict[Tuple[Any, ...], int] = {}
            for row in filtered:
                key = tuple(
                    _value_key(evaluate(expression, row, None))
                    for expression in group_by
                )
                index = group_lookup.get(key)
                if index is None:
                    group_lookup[key] = len(groups)
                    groups.append([row])
                else:
                    groups[index].append(row)
        else:
            # Without GROUP BY every query has exactly one group, even when
            # there are no input rows.
            groups = [filtered]

        for group in groups:
            row = group[0] if group else None
            if having is not None and not _truth(evaluate(having, row, group)):
                continue
            values = tuple(evaluate(item.expr, row, group) for item in items)
            keys = _make_order_keys(order_keys, values, row, group)
            entries.append((values, keys))

    if query.distinct:
        seen = set()
        distinct_entries: List[Tuple[Tuple[Any, ...], List[Any]]] = []
        for values, keys in entries:
            key = tuple(_value_key(value) for value in values)
            if key not in seen:
                seen.add(key)
                distinct_entries.append((values, keys))
        entries = distinct_entries

    if order_keys:
        def compare_entries(
            left: Tuple[Tuple[Any, ...], List[Any]],
            right: Tuple[Tuple[Any, ...], List[Any]],
        ) -> int:
            for order_key, left_value, right_value in zip(
                order_keys, left[1], right[1]
            ):
                comparison = _compare_for_sort(
                    left_value, right_value, order_key.desc
                )
                if comparison != 0:
                    return comparison
            return 0

        entries = sorted(entries, key=cmp_to_key(compare_entries))

    offset = query.offset if query.offset is not None else 0
    if query.limit is not None:
        entries = entries[offset : offset + query.limit]
    elif offset:
        entries = entries[offset:]

    return Result(columns, [values for values, _ in entries])


def _make_order_keys(
    order_keys: Sequence[_OrderKey],
    values: Tuple[Any, ...],
    row: Optional[Tuple[Any, ...]],
    group: Optional[List[Tuple[Any, ...]]],
) -> List[Any]:
    keys: List[Any] = []
    for order_key in order_keys:
        if order_key.index is not None:
            keys.append(values[order_key.index])
        else:
            keys.append(evaluate(order_key.expr, row, group))  # type: ignore[arg-type]
    return keys

